# Decorator preserving metadata (use functools.wraps):
def log_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with {args}")
        result = func(*args, **kwargs)
        print(f"Returned: {result}")
        return result
    return wrapper

