from functools import wraps

# Decorator with arguments (three-level nesting):
def repeat(n: int = 1):
    """Repeat function call n times."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(n):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def say(msg):
    print(msg)

say("Hello!")
# Hello!
# Hello!
# Hello!

