# Decorator that can be used both with and without arguments:
def logged(func_or_prefix):
    if callable(func_or_prefix):
        @wraps(func_or_prefix)
        def wrapper(*args, **kwargs):
            print(f"Calling {func_or_prefix.__name__}")
            return func_or_prefix(*args, **kwargs)
        return wrapper
    else:
        prefix = func_or_prefix
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                print(f"[{prefix}] Calling {func.__name__}")
                return func(*args, **kwargs)
            return wrapper
        return decorator

@logged
def func1():
    pass  # logged(func1) - no args

@logged("APP")
def func2():
    pass  # logged("APP")(func2) - with args

# Decorator with optional arguments (default=1):
def retry(max_attempts: int = 1, delay: float = 0.0):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts - 1:
                        raise
                    if delay:
                        import time
                        time.sleep(delay)
            return None
        return wrapper
    return decorator

@retry(max_attempts=3, delay=0.5)
