    if random.random() < 0.7:
        raise ValueError("Random failure")
    return "Success"

class Calculator:
    # Class variable
    description = "A simple calculator"

    def __init__(self, name: str):
        self.name = name

    # Regular instance method:
    def add(self, a, b):
        return a + b

    # Class method — receives class as first argument:
    @classmethod
    def from_version(cls, version: int):
        """Factory method that creates instance based on version."""
        if version == 1:
            return cls("Basic")
        elif version == 2:
            return cls("Advanced")
        return cls("Default")

    @classmethod
    def get_description(cls):
        return cls.description

    # Static method — no self or cls:
    @staticmethod
    def validate_number(n):
        return isinstance(n, (int, float)) and n >= 0

    @staticmethod
    def convert_temp(celsius):
        return celsius * 9/5 + 32

# Instance:
calc = Calculator("MyCalc")
print(calc.add(3, 4))  # 7

# Class method (called on class):
calc2 = Calculator.from_version(2)
print(calc2.name)  # Advanced
print(Calculator.get_description())  # A simple calculator

# Static method (called on class or instance):
print(Calculator.validate_number(-5))  # False
print(calc.validate_number(10))  # True
print(Calculator.convert_temp(100))  # 212.0

class Temperature:
    def __init__(self, celsius: float = 0):
        self._celsius = celsius

    @property
    def celsius(self) -> float:
        """Get temperature in Celsius."""
        return self._celsius

    @celsius.setter
    def celsius(self, value: float):
        """Set temperature with validation."""
        if value < -273.15:
            raise ValueError("Temperature below absolute zero!")
        self._celsius = value

    @celsius.deleter
    def celsius(self):
        print("Deleting temperature")
        del self._celsius

    @property
    def fahrenheit(self) -> float:
        """Convert to Fahrenheit (read-only property)."""
        return self._celsius * 9/5 + 32

    @property
    def kelvin(self) -> float:
        return self._celsius + 273.15

# Usage:
temp = Temperature(25)
print(temp.celsius)      # 25 (getter)
print(temp.fahrenheit)   # 77.0 (read-only property)
print(temp.kelvin)       # 298.15

temp.celsius = 100       # setter
print(temp.fahrenheit)  # 212.0

