# Recursive directory walk:
from pathlib import Path

def tree(path, indent=""):
    p = Path(path)
    if p.is_dir():
        print(f"{indent}[{p.name}/]")
        for child in p.iterdir():
            tree(child, indent + "  ")
    else:
        print(f"{indent} {p.name}")

# When recursion is bad:
# · Deep recursion exceeds stack limit
# · Higher overhead than iteration
# · Use iteration or memoization when possible

# Tail recursion (Python doesn't optimize this):
def factorial_tail(n, acc=1):
    if n <= 1:
        return acc
    return factorial_tail(n - 1, acc * n)  # Still uses stack!

print(factorial_tail(5))  # 120

from functools import singledispatch

@singledispatch
def process(value):
    """Default handler."""
    print(f"Unknown type: {type(value)}")

# Register handlers for specific types:
@process.register(int)
def _(value):
    print(f"Integer: {value}")

@process.register(str)
def _(value):
    print(f"String: {value}")

@process.register(list)
def _(value):
    print(f"List with {len(value)} items: {value}")

@process.register(dict)
def _(value):
    print(f"Dict with keys: {list(value.keys())}")

# Works with isinstance logic:
process(42)                    # Integer: 42
process("hello")               # String: hello
process([1, 2, 3])             # List with 3 items: [1, 2, 3]
process({"a": 1})             # Dict with keys: ['a']
process(3.14)                  # Unknown type: <class 'float'>

# Can also register using annotation:
@process.register
def _(value: set):
    print(f"Set with {len(value)} elements")

process({1, 2, 3})  # Set with 3 elements

# Stacked registrations for inheritance:
@process.register(tuple)
def _(value):
    print(f"Tuple: {value}")

# Dispatch also works with abstract types:
from collections.abc import Iterable

@process.register(Iterable)
def _(value):
    print(f"Iterable: {value}")  # Won't override specific types

# Check registered types:
print(process.dispatch(int))    # <function _ at 0x...>
print(process.registry.keys())  # All registered types

# Real use: serialization
@singledispatch
def to_json(val):
    raise TypeError(f"Cannot serialize {type(val)}")

@to_json.register(int)
@to_json.register(float)
def _(val):
    return str(val)

@to_json.register(bool)
def _(val):
    return "true" if val else "false"

@to_json.register(str)
def _(val):
    return f'"{val}"'

@to_json.register(list)
def _(val):
    items = ", ".join(to_json(v) for v in val)
    return f"[{items}]"
